import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const entryId = "src/app.js";
const modules = new Map();
const moduleOrder = [];

function modulePath(moduleId) {
  const filePath = path.resolve(projectRoot, ...moduleId.split("/"));
  const sourceRoot = path.resolve(projectRoot, "src");
  if (filePath !== sourceRoot && !filePath.startsWith(`${sourceRoot}${path.sep}`)) {
    throw new Error(`Unsupported module path: ${moduleId}`);
  }
  return filePath;
}

function normalizeModuleId(fromId, specifier) {
  if (!specifier.startsWith(".")) throw new Error(`Unsupported external import: ${specifier}`);
  return path.posix.normalize(path.posix.join(path.posix.dirname(fromId), specifier));
}

function parseImportBindings(specifierList) {
  return specifierList
    .split(",")
    .map((specifier) => specifier.trim())
    .filter(Boolean)
    .map((specifier) => {
      const [imported, local = imported] = specifier.split(/\s+as\s+/);
      return `${imported.trim()}: ${local.trim()}`;
    });
}

function parseExportBindings(specifierList) {
  return specifierList
    .split(",")
    .map((specifier) => specifier.trim())
    .filter(Boolean)
    .map((specifier) => {
      const [local, exported = local] = specifier.split(/\s+as\s+/);
      return { local: local.trim(), exported: exported.trim() };
    });
}

function collectModule(moduleId) {
  if (modules.has(moduleId)) return;
  modules.set(moduleId, { source: null });

  let source = fs.readFileSync(modulePath(moduleId), "utf8");
  const importPattern = /(^|\r?\n)[ \t]*import\s*\{([\s\S]*?)\}\s*from\s*["']([^"']+)["'];?[ \t]*(?=\r?\n|$)/g;
  source = source.replace(importPattern, (match, linePrefix, specifierList, specifier) => {
    const dependencyId = normalizeModuleId(moduleId, specifier);
    collectModule(dependencyId);
    const bindings = parseImportBindings(specifierList);
    return `${linePrefix}const { ${bindings.join(", ")} } = __require(${JSON.stringify(dependencyId)});`;
  });

  const sideEffectImportPattern = /(^|\r?\n)[ \t]*import\s*["']([^"']+)["'];?[ \t]*(?=\r?\n|$)/g;
  source = source.replace(sideEffectImportPattern, (match, linePrefix, specifier) => {
    const dependencyId = normalizeModuleId(moduleId, specifier);
    collectModule(dependencyId);
    return `${linePrefix}__require(${JSON.stringify(dependencyId)});`;
  });

  const exportFromPattern = /(^|\r?\n)[ \t]*export\s*\{([\s\S]*?)\}\s*from\s*["']([^"']+)["'];?[ \t]*(?=\r?\n|$)/g;
  source = source.replace(exportFromPattern, (match, linePrefix, specifierList, specifier) => {
    const dependencyId = normalizeModuleId(moduleId, specifier);
    collectModule(dependencyId);
    const bindings = parseExportBindings(specifierList);
    const lines = bindings.map(({ local, exported }) => (
      `const { ${local}: ${local} } = __require(${JSON.stringify(dependencyId)}); exports.${exported} = ${local};`
    ));
    return `${linePrefix}${lines.join("\n")}`;
  });

  const exportedNames = [];
  const exportPattern = /(^|\r?\n)([ \t]*)export\s+(async\s+function|function|const|class)\s+([A-Za-z_$][\w$]*)/g;
  source = source.replace(exportPattern, (match, linePrefix, indentation, declaration, name) => {
    exportedNames.push(name);
    return `${linePrefix}${indentation}${declaration} ${name}`;
  });

  if (/^\s*(?:import|export)\b/m.test(source)) {
    throw new Error(`Unsupported ESM syntax in ${moduleId}`);
  }

  source = source.replace(/[ \t]+(?=\r?$)/gm, "");
  source = `${source.trimEnd()}\n${exportedNames.map((name) => `exports.${name} = ${name};`).join("\n")}`;
  modules.get(moduleId).source = source;
  moduleOrder.push(moduleId);
}

function indent(source, spaces) {
  const prefix = " ".repeat(spaces);
  return source
    .split("\n")
    .map((line) => line.trim() ? `${prefix}${line}` : "")
    .join("\n");
}

function buildBundle() {
  collectModule(entryId);
  const lines = [
    "/* Generated by tools/build-file-bundle.mjs. Edit src/ modules instead. */",
    "(function (global) {",
    '  "use strict";',
    "  const moduleFactories = Object.create(null);",
    "  const moduleCache = Object.create(null);",
    "  function __require(id) {",
    "    if (moduleCache[id]) return moduleCache[id];",
    "    const factory = moduleFactories[id];",
    "    if (!factory) throw new Error(`Unknown bundled module: ${id}`);",
    "    const exports = {};",
    "    moduleCache[id] = exports;",
    "    factory(exports, __require);",
    "    return exports;",
    "  }",
  ];

  for (const moduleId of moduleOrder) {
    lines.push(`  moduleFactories[${JSON.stringify(moduleId)}] = function (exports, __require) {`);
    lines.push(indent(modules.get(moduleId).source, 4));
    lines.push("  };");
  }

  lines.push(`  __require(${JSON.stringify(entryId)});`);
  lines.push('  global.MinesweeperFileRuntime = Object.freeze({ ready: true });');
  lines.push("})(window);");
  return `${lines.join("\n")}\n`;
}

const outputPath = path.join(projectRoot, "dist", "file-bundle.js");
fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(outputPath, buildBundle(), "utf8");
process.stdout.write(`Built ${path.relative(projectRoot, outputPath)}\n`);
